from solution import make_palindrome, is_palindrome
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference_make_palindrome(s: str) -> str:
    # Obviously-correct model directly from spec:
    # smallest i such that s[i:] is palindrome (longest palindromic postfix),
    # then append reverse of s[:i].
    for i in range(len(s) + 1):
        if s[i:] == s[i:][::-1]:
            return s + s[:i][::-1]
    raise AssertionError("unreachable")


# ---- explicit examples from spec ----

def test_example_empty():
    assert make_palindrome('') == ''


def test_example_cat():
    assert make_palindrome('cat') == 'catac'


def test_example_cata():
    assert make_palindrome('cata') == 'catac'


# ---- properties ----

@given(st.text(alphabet='abc', max_size=10))
def test_result_begins_with_input(s):
    r = make_palindrome(s)
    assert r.startswith(s)


@given(st.text(alphabet='abc', max_size=10))
def test_result_is_palindrome(s):
    r = make_palindrome(s)
    assert is_palindrome(r)
    assert r == r[::-1]


@given(st.text(alphabet='ab', max_size=12))
def test_matches_reference_model(s):
    assert make_palindrome(s) == reference_make_palindrome(s)


@given(st.text(alphabet='abc', max_size=10))
def test_shortest_no_shorter_palindrome_with_prefix(s):
    r = make_palindrome(s)
    # Any string beginning with s and shorter than r cannot be a palindrome.
    # Every such string of length L is the prefix of r of length L,
    # so check all proper prefixes of r with length >= len(s).
    for L in range(len(s), len(r)):
        prefix = r[:L]
        assert prefix != prefix[::-1], f"shorter palindrome {prefix!r} exists for {s!r}"


@given(st.text(alphabet='abc', max_size=10))
def test_length_bounds(s):
    r = make_palindrome(s)
    assert len(r) >= len(s)
    if s == '':
        assert r == ''
    else:
        # appending at most len(s)-1 chars (reverse of proper prefix)
        assert len(r) <= 2 * len(s) - 1


@given(st.text(alphabet='abc', max_size=10))
def test_idempotence_result_is_fixed_point(s):
    r = make_palindrome(s)
    assert make_palindrome(r) == r


@given(st.text(alphabet='abc', max_size=10))
def test_palindromic_input_returned_unchanged(s):
    assume(is_palindrome(s))
    assert make_palindrome(s) == s


@given(st.text(alphabet='abc', min_size=1, max_size=1))
def test_single_char_unchanged(s):
    assert make_palindrome(s) == s


@given(st.text(alphabet='abc', max_size=10))
def test_appended_part_is_reverse_of_prefix(s):
    r = make_palindrome(s)
    added = r[len(s):]
    assert added == added[::-1][::-1]  # sanity
    # The added part plus the palindromic suffix must mirror the prefix:
    # r == s + reverse(s[:i]) for some i where s[i:] is palindrome
    found = False
    for i in range(len(s) + 1):
        if s[i:] == s[i:][::-1] and r == s + s[:i][::-1]:
            found = True
            break
    assert found, f"{r!r} not of form s + reverse(prefix) with palindromic suffix for {s!r}"
